import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const ephysRoot = path.join(root, "apps/electrophysiology-lab/src");
const pspRoot = path.join(root, "apps/psp-lab/src");
const outputPath = path.join(pspRoot, "app.bundle.js");

// The source remains modular and testable. This deterministic copy uses a
// classic script so PSP Lab can also open directly from file:// in Safari.
const modules = [
  {
    name: "signalModule",
    root: ephysRoot,
    file: "core/signal.js",
    exports: ["median", "medianAbsoluteDeviation"],
  },
  {
    name: "pspScenarioModule",
    root: ephysRoot,
    file: "core/pspScenario.js",
    exports: ["createSeededRandom", "createStudentScenarioView", "generatePspScenario"],
  },
  {
    name: "currentClampModule",
    root: ephysRoot,
    file: "core/currentClamp.js",
    prelude: "const { median, medianAbsoluteDeviation } = signalModule;",
    exports: ["measureEvokedPsps"],
  },
  {
    name: "pspPlotModule",
    root: pspRoot,
    file: "plot.js",
    exports: ["PspPlot"],
  },
];

function removeModuleSyntax(source) {
  return source
    .replace(/^import\b[\s\S]*?;\s*/gm, "")
    .replace(/^export\s+/gm, "");
}

function indent(source, spaces = 2) {
  const padding = " ".repeat(spaces);
  return source.split("\n").map((line) => `${padding}${line}`).join("\n");
}

const sections = [
  "/* Generated by scripts/build-psp-lab-bundle.mjs. Edit src modules, not this file. */",
  "(() => {",
  "  \"use strict\";",
];

for (const moduleDefinition of modules) {
  const source = removeModuleSyntax(
    await readFile(path.join(moduleDefinition.root, moduleDefinition.file), "utf8"),
  ).trim();
  sections.push(`  const ${moduleDefinition.name} = (() => {`);
  if (moduleDefinition.prelude) sections.push(`    ${moduleDefinition.prelude}`);
  sections.push(indent(source, 4));
  sections.push(`    return { ${moduleDefinition.exports.join(", ")} };`);
  sections.push("  })();");
}

const appSource = removeModuleSyntax(await readFile(path.join(pspRoot, "app.js"), "utf8")).trim();
sections.push("  (() => {");
sections.push("    const { createSeededRandom, createStudentScenarioView, generatePspScenario } = pspScenarioModule;");
sections.push("    const { measureEvokedPsps } = currentClampModule;");
sections.push("    const { PspPlot } = pspPlotModule;");
sections.push(indent(appSource, 4));
sections.push("  })();");
sections.push("})();", "");

const bundle = sections.join("\n");
if (process.argv.includes("--check")) {
  const currentBundle = await readFile(outputPath, "utf8").catch(() => "");
  if (currentBundle !== bundle) {
    throw new Error("PSP Lab app.bundle.js está desactualizado; ejecuta node scripts/build-psp-lab-bundle.mjs");
  }
} else {
  await writeFile(outputPath, bundle, "utf8");
}
